import org.springframework.mail.SimpleMailMessage;
import org.springframework.mail.javamail.JavaMailSender;
import org.springframework.stereotype.Service;

/**
 * Sends the plain-text verification-code emails through the auto-configured
 * {@link JavaMailSender} (retained {@code spring.mail.*} properties pointing at
 * the mock SMTP service). A send failure never propagates into the API call: it
 * is logged to stderr and swallowed.
 */
@Service
public class EmailService {

    private static final String FROM_ADDRESS = "noreply@secureid.com";
    private static final String REGISTER_SUBJECT = "SecureID 邮箱验证码";
    private static final String RESET_SUBJECT = "SecureID 密码重置验证码";

    private final JavaMailSender mailSender;

    public EmailService(JavaMailSender mailSender) {
        this.mailSender = mailSender;
    }

    /**
     * Sends a REGISTER-flow verification code to the given address.
     */
    public void sendRegisterCode(String to, String code) {
        sendCodeEmail(to, REGISTER_SUBJECT, code);
    }

    /**
     * Sends a RESET-flow verification code to the given address.
     */
    public void sendResetCode(String to, String code) {
        sendCodeEmail(to, RESET_SUBJECT, code);
    }

    private void sendCodeEmail(String to, String subject, String code) {
        try {
            SimpleMailMessage message = new SimpleMailMessage();
            message.setFrom(FROM_ADDRESS);
            message.setTo(to);
            message.setSubject(subject);
            message.setText("您的验证码是：" + code + "，有效期10分钟。");
            mailSender.send(message);
        } catch (Exception e) {
            System.err.println("Failed to send verification email to " + to + ": " + e);
            e.printStackTrace();
        }
    }
}
